def restore_bitset_composed_text_index_history(source):
    """Remove only the exact authenticated priority layer for historical checks."""
    digest = hashlib.sha256(source).hexdigest()
    assert digest in {R19_BITSET_COMPOSED_TEXT_INDEX_REGISTERED_SHA256,R19_BITSET_COMPOSED_TEXT_INDEX_MAINTAINED_SHA256}
    assert source.count(_R19_BITSET_COMPOSED_TEXT_INDEX_ADDITIONS) == 1
    restored = source.replace(_R19_BITSET_COMPOSED_TEXT_INDEX_ADDITIONS,b'',1)
    expected = (R19_BITSET_COMPOSED_TEXT_INDEX_PREVIOUS_REGISTERED_SHA256 if digest == R19_BITSET_COMPOSED_TEXT_INDEX_REGISTERED_SHA256
                else R19_BITSET_COMPOSED_TEXT_INDEX_PREVIOUS_MAINTAINED_SHA256)
    assert hashlib.sha256(restored).hexdigest() == expected
    return restored


