def restore_variant_metadata_layout_history(source):
    """Remove only the exact variant metadata and layout layer for historical checks."""
    digest = hashlib.sha256(source).hexdigest()
    assert digest in {R19_VARIANT_METADATA_LAYOUT_REGISTERED_SHA256,R19_VARIANT_METADATA_LAYOUT_MAINTAINED_SHA256}
    assert source.count(_R19_VARIANT_METADATA_LAYOUT_ADDITIONS) == 1
    restored = source.replace(_R19_VARIANT_METADATA_LAYOUT_ADDITIONS,b'',1)
    expected = (R19_VARIANT_METADATA_LAYOUT_PREVIOUS_REGISTERED_SHA256 if digest == R19_VARIANT_METADATA_LAYOUT_REGISTERED_SHA256
                else R19_VARIANT_METADATA_LAYOUT_PREVIOUS_MAINTAINED_SHA256)
    assert hashlib.sha256(restored).hexdigest() == expected
    return restored


